// WRITTEN FOR THIS REPO -- NOT OpenTitan source.  See README.md.
//
// prim_fifo_async.sv instantiates prim_flop_2sync for its Gray-coded pointer
// crossings.  Upstream prim_flop_2sync is an "abstract prim": the wrapper is
// generated by OpenTitan's build system and the implementation is selected per
// technology, so there is no single source file to vendor.  This is the two
// flops it comes down to.
//
// TAPEOUT NOTE: this is the one place the link's CDC depends on metastability
// behaviour.  Replace it with the PDK's hardened synchroniser cell when the
// 65 nm library lands, and give both flops a `set_false_path` / don't-touch so
// the tool cannot optimise the two stages into one.
module prim_flop_2sync #(
  parameter Width = 1
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);

  logic [Width-1:0] stage1;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      stage1 <= '0;
      q_o    <= '0;
    end else begin
      stage1 <= d_i;
      q_o    <= stage1;
    end
  end

endmodule
